/**
 * The local Host's background check: only an upgrade (`backgroundUpgrade
 * Daemon installed in `home`, once per connection. Null when the app runs its own.
 */
export const localBackgroundUpgradeKey = (
  view: HostView,
  bundledVersion: string | null,
  home: string | null
): string | null => {
  const { status } = view;

  if (home === null || bundledVersion === null) return null;

  if (status.state === "connected" && status.host !== null && bundledVersion !== null) {
    return backgroundUpgradeDue(status.host.daemonVersion, bundledVersion)
      ? `background-upgrade:${status.epoch}`
      : null;
  }

  return null;
};

/**
 * The local Host's background check: only an upgrade (`backgroundUpgradeDue`)
 * of the Daemon installed in `home`, once per connection. Null when the app runs its own.
 */
export const localUpgradeKey = (
  view: HostView,
  bundledVersion: string | null,
  home: string | null
): string | null => {
  const { status } = view;

